#include <windows.h>
#include <stdio.h>

int main() {
    const char name[] = "\\\\.\\pipe\\NtExplorerExample";
    HANDLE server = CreateNamedPipeA(name, PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT, 1, 0, 0, 0, nullptr);
    if (server == INVALID_HANDLE_VALUE) {
        return 1;
    }

    HANDLE client = CreateFileA(name, GENERIC_READ | GENERIC_WRITE, 0,
        nullptr, OPEN_EXISTING, 0, nullptr);
    if (client == INVALID_HANDLE_VALUE) {
        CloseHandle(server);
        return 1;
    }

    BOOL connected = ConnectNamedPipe(server, nullptr) ||
        GetLastError() == ERROR_PIPE_CONNECTED;
    printf("Connected: %s\n", connected ? "yes" : "no");

    CloseHandle(client);
    CloseHandle(server);
    return 0;
}

