int main() {
    char temp_path[MAX_PATH] = {};
    char file_path[MAX_PATH] = {};
    GetTempPathA(MAX_PATH, temp_path);
    GetTempFileNameA(temp_path, "nte", 0, file_path);

    HANDLE file = CreateFileA(file_path, GENERIC_READ | GENERIC_WRITE, 0,
        nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        return 1;
    }

    // FSCTL_GET_COMPRESSION is read-only and works on an ordinary file.
    USHORT compression = 0;
    DWORD returned = 0;
    if (DeviceIoControl(file, FSCTL_GET_COMPRESSION, nullptr, 0,
            &compression, sizeof(compression), &returned, nullptr)) {
        printf("Compression format: %u\n", compression);
    }

    CloseHandle(file);
    DeleteFileA(file_path);
    return 0;
}

